import { memoize, memoizeSync } from "../src/index.js";

// Example 1: Fibonacci with memoization
function example1() {
  console.log("=== Example 1: Fibonacci with Memoization ===");

  const fibonacci = memoizeSync(
    (n: number): number => {
      if (n <= 1) return n;
      return fibonacci(n - 1) + fibonacci(n - 2);
