      window.setData = async function () {
        const key = `user:${Math.floor(Math.random() * 100)}`;
        const value = {
          id: key,
          name: `User ${key}`,
          timestamp: Date.now(),
        };

        await cache.set(key, value, {
          tags: ["users", "demo"],
        });

        log(`Set ${key}`);
        await showStats();
      };

      // Get data
      window.getData = async function () {
        const key = `user:${Math.floor(Math.random() * 100)}`;
        const value = await cache.get(key);

        if (value) {
          log(`Got ${key}: ${JSON.stringify(value)}`);
        } else {
          log(`${key} not found`);
        }

        await showStats();
      };

      // Invalidate by tag
      window.invalidateByTag = async function () {
        await cache.invalidateByTag("users");
        log("Invalidated all users");
        await showStats();
      };

      // Clear cache
      window.clearCache = async function () {
        await cache.clear();
        log("Cache cleared");
        await showStats();
      };

      // Show stats
      window.showStats = async function () {
        const stats = await cache.getStats();
        const statsDiv = document.getElementById("stats");
        statsDiv.innerHTML = `
        <h3>Cache Statistics</h3>
        <p><strong>Size:</strong> ${stats.size} entries</p>
        <p><strong>Hits:</strong> ${stats.hits}</p>
        <p><strong>Misses:</strong> ${stats.misses}</p>
        <p><strong>Hit Rate:</strong> ${stats.hitRate.toFixed(2)}%</p>
        <p><strong>Sets:</strong> ${stats.sets}</p>
        <p><strong>Deletes:</strong> ${stats.deletes}</p>
      `;
