interface CacheFnConfig {
  name: string;
  storage?: 'memory' | 'indexeddb';
  maxSize?: number;
  defaultTTL?: number;
  namespace?: string;
}

interface SetOptions {
  ttl?: number;
  tags?: string[];
}

interface CacheEntry<T> {
  key: string;
  value: T;
  createdAt: number;
  expiresAt?: number;
  tags?: string[];
  hits: number;
  lastAccess: number;
}

