      context: context({
        actor: { id: "user_1", permissions: ["examplefn.records.rotate"] },
        idempotencyKey: "attempted",
      }),
    });
    const result = await dispatch();

    expect(handler).not.toHaveBeenCalled();
    expect(attempted[0]).toMatchObject({
