        typeof error === "object" &&
        error !== null &&
        "code" in error &&
        "message" in error &&
        "recoverable" in error
          ? (error as DrawfnError)
          : createDrawfnError("EXPORT_RENDER_FAILED", "Failed to export PNG.", {
              cause: error instanceof Error ? error.message : String(error),
