import { resolve, extname } from 'node:path';
import { pathToFileURL } from 'node:url';
import type { Adapter } from '@superfunctions/db';
import type { CompFnConfig, Logger } from 'compfn';

export interface CliConfig extends Omit<CompFnConfig, 'database'> {
  database: Adapter;
}

const stderrLogger: Logger = {
  debug: () => {},
  info: (message, context) => console.error(message, context ?? ''),
  warn: (message, context) => console.error(message, context ?? ''),
  error: (message, context) => console.error(message, context ?? ''),
};

/** Module configuration supplies a real shared DB adapter and evidence clients. */
export async function loadConfig(configPath?: string): Promise<CliConfig> {
  const resolvedPath = resolve(configPath ?? process.env.COMPFN_CONFIG ?? 'compfn.config.json');
  let config: CliConfig;
  if (['.js', '.mjs', '.cjs'].includes(extname(resolvedPath))) {
    const module = await import(pathToFileURL(resolvedPath).href);
    config = typeof module.default === 'function' ? await module.default() : await module.default;
  } else {
    const parsed = JSON.parse(readFileSync(resolvedPath, 'utf8'));
    const databaseType = parsed.database?.type ?? 'memory';
    if (databaseType !== 'memory') {
      throw new Error(`Database type ${databaseType} requires a .mjs/.js/.cjs config exporting a shared DB adapter`);
    }
    const { memoryAdapter } = await import('@superfunctions/db/adapters');
    config = { ...parsed, database: memoryAdapter() };
  }
  if (!config || typeof config !== 'object' ||
      !config.database || typeof config.database.initialize !== 'function' ||
      typeof config.database.close !== 'function' || typeof config.database.create !== 'function') {
    throw new Error('Config must export a CompFn config with a shared database Adapter');
  }
  for (const [name, adapter] of Object.entries(config.adapters ?? {})) {
    if (!adapter || typeof adapter.runCheck !== 'function') {
      throw new Error(`Evidence adapter ${name} must provide runCheck; configure adapters in a module config`);
    }
  }
  return { ...config, logger: config.logger ?? stderrLogger };
}

/** Commands flush output normally and always close the database they initialized. */
export async function withConfig(path: string | undefined, run: (config: CliConfig) => Promise<void>): Promise<void> {
  let config: CliConfig | undefined;
  try {
    config = await loadConfig(path);
    await config.database.initialize();
    await run(config);
  } catch (error) {
    console.error(`Error: ${error instanceof Error ? error.message : String(error)}`);
    process.exitCode = 1;
  } finally {
    if (config) {
      try { await config.database.close(); }
      catch (error) {
        console.error(`Error closing database: ${error instanceof Error ? error.message : String(error)}`);
        process.exitCode = 1;
      }
    }
  }
}
#!/usr/bin/env node

import { Command } from "commander";
import { initCommand } from "./commands/init.js";
import { runChecksCommand } from "./commands/run-checks.js";
import { exportCommand } from "./commands/export.js";
import { attestCommand } from "./commands/attest.js";

const program = new Command();

program
  .name("compfn")
  .description("CompFn CLI: compliance automation tool")
  .version("0.1.0");

program
  .command("init")
  .description("Initialize config and DB schema")
  .option("-c, --config <path>", "Path to config file")
  .action(initCommand);

program
  .command("run-checks")
  .description("Run checks (all or one)")
  .option("--check-id <id>", "Run a specific check by ID")
  .option("-c, --config <path>", "Path to config file")
  .action(runChecksCommand);

program
  .command("export")
  .description("Export auditor pack")
  .option("--framework-id <id>", "Framework ID to export")
  .option("--output <path>", "Output file path (default: stdout)")
  .option("-c, --config <path>", "Path to config file")
  .action(exportCommand);

program
  .command("attest")
  .description("Create manual attestation evidence")
  .requiredOption("--control-id <id>", "Control ID")
  .requiredOption("--actor-id <id>", "Actor ID")
  .option("--outcome <pass|fail>", "Outcome (default: pass)")
  .option("-c, --config <path>", "Path to config file")
  .action(attestCommand);

await program.parseAsync(process.argv);
import { withConfig } from "../config.js";
import { compFn, createSchemaIfSupported } from "compfn";

export async function initCommand(options: { config?: string }): Promise<void> {
  return withConfig(options.config, async (config) => {

    const result = await createSchemaIfSupported(config.database, {
      namespace: config.namespace,
    });

    if (!result.success) {
      console.error("Schema creation/migration failed:");
      result.errors?.forEach((err) => console.error(`  - ${err}`));
      process.exitCode = 1;
      return;
    }

    console.log("CompFn initialized successfully.");
    return;
  });
}
import { withConfig } from "../config.js";
import { compFn } from "compfn";

export async function attestCommand(options: {
  controlId: string;
  actorId: string;
  outcome?: "pass" | "fail";
  config?: string;
}): Promise<void> {
  return withConfig(options.config, async (config) => {
    const api = compFn(config);

    const outcome = options.outcome ?? "pass";

    const evidenceResult = await api.evidence.create({
      controlId: options.controlId,
      type: "manual_attestation",
      actorId: options.actorId,
      outcome,
    });

    if (!evidenceResult.ok) {
      console.error(`Error creating attestation: ${evidenceResult.error.message}`);
      process.exitCode = 1;
      return;
    }

    console.log(`Attestation created: ${evidenceResult.result.id}`);
    return;
  });
}
import { withConfig } from "../config.js";
import { compFn } from "compfn";

export async function runChecksCommand(options: { checkId?: string; config?: string }): Promise<void> {
  return withConfig(options.config, async (config) => {
    const api = compFn(config);

    let checksToRun: string[] = [];

    if (options.checkId) {
      checksToRun = [options.checkId];
    } else {
      const listResult = await api.checks.list();
      if (!listResult.ok) {
        console.error(`Error listing checks: ${listResult.error.message}`);
        process.exitCode = 1;
      return;
      }
      checksToRun = listResult.result.map((check) => check.id);
    }

    if (checksToRun.length === 0) {
      console.log("No checks to run.");
      return;
    }

    let passCount = 0;
    let failCount = 0;
    let unknownCount = 0;

    for (const checkId of checksToRun) {
      const runResult = await api.checks.run(checkId);
      if (!runResult.ok) {
        console.error(`Error running check ${checkId}: ${runResult.error.message}`);
        failCount++;
        continue;
      }

      const outcome = runResult.result.outcome;
      if (outcome === "pass") {
        passCount++;
      } else if (outcome === "fail") {
        failCount++;
      } else {
        unknownCount++;
      }
    }

    const total = checksToRun.length;
    console.log(`Ran ${total} check${total !== 1 ? "s" : ""}: ${passCount} pass, ${failCount} fail${unknownCount > 0 ? `, ${unknownCount} unknown` : ""}`);
    if (failCount > 0) process.exitCode = 1;
  });
}
import { writeFileSync } from "fs";
import { withConfig } from "../config.js";
import { compFn } from "compfn";

export async function exportCommand(options: {
  frameworkId?: string;
  output?: string;
  config?: string;
}): Promise<void> {
  return withConfig(options.config, async (config) => {
    const api = compFn(config);

    const exportResult = await api.export.auditorPack({
      frameworkId: options.frameworkId,
    });

    if (!exportResult.ok) {
      console.error(`Error exporting auditor pack: ${exportResult.error.message}`);
      process.exitCode = 1;
      return;
    }

    const json = JSON.stringify(exportResult.result, null, 2);

    if (options.output) {
      writeFileSync(options.output, json, "utf-8");
      console.log(`Auditor pack exported to ${options.output}`);
    } else {
      console.log(json);
    }

    return;
  });
}
