  let frameworkInput = bundle.framework;
  if (options?.useStableControlIds && controlIdMap.size > 0) {
    frameworkInput = {
      ...bundle.framework,
      requirements: bundle.framework.requirements.map((req) => ({
        ...req,
        controlIds: req.controlIds.map((cid) => controlIdMap.get(cid) ?? cid),
      })),
    };
  }

