/**
 * Bundle loader utilities for loading framework bundles into compfn.
 * Bundles contain framework definitions and optional control definitions.
 */

import type { CompFnAPI } from "../api.js";
import type { CreateFrameworkInput } from "../framework.js";
import type { CreateControlInput } from "../control.js";
import type { CompfnEnvelope } from "../types.js";

export interface FrameworkBundle {
  framework: CreateFrameworkInput;
  controls?: CreateControlInput[];
}

export interface BundleLoadResult {
  framework: { id: string; name: string };
  controls: Array<{ id: string; name: string }>;
}

/**
 * Load a framework bundle into compfn.
 * Creates all controls first (if present in bundle), then creates the framework.
 * 
 * @param api - The compfn API instance
 * @param bundle - The framework bundle to load
 * @param options - Optional configuration
 * @returns Envelope with load result (framework id/name and control ids/names)
 */
export async function loadBundle(
  api: CompFnAPI,
  bundle: FrameworkBundle,
  options?: {
    /**
     * If true, use control IDs from bundle as-is when creating controls.
     * If false or undefined, let compfn generate IDs.
     */
    useStableControlIds?: boolean;
  }
): Promise<CompfnEnvelope<BundleLoadResult>> {
  const createdControls: Array<{ id: string; name: string }> = [];
  const controlIdMap = new Map<string, string>(); // bundle id -> created id

  // Step 1: Create controls from bundle (if any)
  if (bundle.controls && bundle.controls.length > 0) {
    for (const controlInput of bundle.controls) {
      // Generate stable ID from control name if needed
      const stableId = options?.useStableControlIds
        ? generateStableControlId(controlInput.name)
        : undefined;

      // Check if control already exists (by stable ID if provided)
      let existingControl;
      if (stableId) {
        existingControl = await api.controls.get(stableId);
        if (existingControl.ok) {
          controlIdMap.set(stableId, stableId);
          createdControls.push({ id: stableId, name: existingControl.result.name });
          continue; // Skip creating if exists
        }
      }

      // Create the control
      const controlResult = await api.controls.create(controlInput);
      if (!controlResult.ok) {
        return controlResult as CompfnEnvelope<BundleLoadResult>;
      }

      const createdControl = controlResult.result;
      if (stableId) {
        controlIdMap.set(stableId, createdControl.id);
      }
      createdControls.push({ id: createdControl.id, name: createdControl.name });
    }
  }

  // Step 2: Update framework requirements with created control IDs if needed
  let frameworkInput = bundle.framework;
  if (options?.useStableControlIds && controlIdMap.size > 0) {
    frameworkInput = {
      ...bundle.framework,
      requirements: bundle.framework.requirements.map((req) => ({
        ...req,
        controlIds: req.controlIds.map((cid) => controlIdMap.get(cid) ?? cid),
      })),
    };
  }

  // Step 3: Create the framework
  const frameworkResult = await api.frameworks.create(frameworkInput);
  if (!frameworkResult.ok) {
    return frameworkResult as CompfnEnvelope<BundleLoadResult>;
  }

  return {
    ok: true,
    result: {
      framework: { id: frameworkResult.result.id, name: frameworkResult.result.name },
      controls: createdControls,
    },
  };
}

/**
 * Generate a stable control ID from a control name.
 * Uses kebab-case conversion.
 */
function generateStableControlId(name: string): string {
  return name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}
/**
 * Tests for framework bundle loading (BUNDLE-001 / PHASE_08).
 * Verifies that framework bundles can be loaded and created successfully.
 */

import { describe, it, expect, beforeEach } from "vitest";
import { memoryAdapter } from "@superfunctions/db/adapters";
import { compFn } from "../compfn.js";
import { loadBundle } from "../bundles/loader.js";
import type { FrameworkBundle } from "../bundles/loader.js";
import { createSchemaIfSupported } from "../storage/adapter.js";

describe("Bundle loading (TV-BUNDLE-001)", () => {
  let api: ReturnType<typeof compFn>;

  beforeEach(async () => {
    const db = memoryAdapter();
    await db.initialize();
    const result = await createSchemaIfSupported(db, { namespace: "compfn" });
    if (!result.success) throw new Error(result.errors?.join("; "));
    api = compFn({ database: db, namespace: "compfn" });
  });

  it("TV-BUNDLE-001: Load framework bundle with controls and create framework successfully", async () => {
    // Arrange: Create a test bundle similar to SOC 2
    const testBundle: FrameworkBundle = {
      framework: {
        name: "SOC 2 Type II",
        version: "2022",
        description: "Test SOC 2 framework bundle",
        requirements: [
          {
            requirementId: "CC6.1",
            name: "Logical and Physical Access Controls",
            controlIds: ["rbac-enabled", "mfa-enforced"],
          },
          {
            requirementId: "CC6.2",
            name: "Prior to Issuing System Credentials",
            controlIds: ["user-provisioning-approved"],
          },
        ],
      },
      controls: [
        {
          name: "RBAC Enabled",
          description: "Role-Based Access Control is implemented and enforced.",
          category: "access-control",
          tags: ["soc2", "security"],
        },
        {
          name: "MFA Enforced",
          description: "Multi-Factor Authentication is required.",
          category: "access-control",
          tags: ["soc2", "security"],
        },
        {
          name: "User Provisioning Approved",
          description: "User account creation requires approval.",
          category: "access-control",
          tags: ["soc2"],
        },
      ],
    };

    // Act: Load the bundle
    const result = await loadBundle(api, testBundle, { useStableControlIds: true });

    // Assert: Bundle loaded successfully
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    // Verify framework was created
    expect(result.result.framework).toBeDefined();
    expect(result.result.framework.name).toBe("SOC 2 Type II");
    expect(result.result.framework.id).toBeDefined();

    // Verify controls were created
    expect(result.result.controls).toHaveLength(3);
    expect(result.result.controls[0].name).toBe("RBAC Enabled");
    expect(result.result.controls[1].name).toBe("MFA Enforced");
    expect(result.result.controls[2].name).toBe("User Provisioning Approved");

    // Verify framework has requirements with controlIds
    const fwResult = await api.frameworks.get(result.result.framework.id);
    expect(fwResult.ok).toBe(true);
    if (!fwResult.ok) return;

    expect(fwResult.result.requirements).toHaveLength(2);
    expect(fwResult.result.requirements[0].requirementId).toBe("CC6.1");
    expect(fwResult.result.requirements[0].controlIds).toHaveLength(2);
    expect(fwResult.result.requirements[1].requirementId).toBe("CC6.2");
    expect(fwResult.result.requirements[1].controlIds).toHaveLength(1);
  });

  it("should load bundle without controls (framework only)", async () => {
    // First create controls manually
    const c1 = await api.controls.create({
      name: "Test Control 1",
      description: "Test",
      category: "test",
    });
    const c2 = await api.controls.create({
      name: "Test Control 2",
      description: "Test",
      category: "test",
    });

    expect(c1.ok).toBe(true);
    expect(c2.ok).toBe(true);
    if (!c1.ok || !c2.ok) return;

    // Create bundle with framework only (no controls array)
    const frameworkOnlyBundle: FrameworkBundle = {
      framework: {
        name: "Test Framework",
        version: "1.0",
        requirements: [
          {
            requirementId: "REQ-001",
            controlIds: [c1.result.id, c2.result.id],
          },
        ],
      },
    };

    // Load the bundle
    const result = await loadBundle(api, frameworkOnlyBundle);

    // Assert
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    expect(result.result.framework.name).toBe("Test Framework");
    expect(result.result.controls).toHaveLength(0); // No controls in bundle
  });

  it("should fail if bundle references non-existent control IDs", async () => {
    // Bundle with invalid control IDs
    const invalidBundle: FrameworkBundle = {
      framework: {
        name: "Invalid Framework",
        requirements: [
          {
            requirementId: "REQ-001",
            controlIds: ["nonexistent-control-id"],
          },
        ],
      },
    };

    // Try to load the bundle
    const result = await loadBundle(api, invalidBundle);

    // Should fail validation
    expect(result.ok).toBe(false);
    if (result.ok) return;
    expect(result.error.code).toBe("VALIDATION_FAILED");
  });

"}

