/**
 * Storage schema for compfn: controls, frameworks, evidence, checks.
 * Tables are namespaced (e.g. compfn_controls) via adapter namespace.
 */

import type { TableSchema, TableSchemaMap } from "@superfunctions/db";

export interface CompfnSchemaOptions {
  namespace?: string;
}

const DEFAULT_NAMESPACE = "compfn";

function ns(options: CompfnSchemaOptions, suffix: string): string {
  const prefix = options.namespace ?? DEFAULT_NAMESPACE;
  return `${prefix}_${suffix}`;
}

export function getCompfnSchema(options: CompfnSchemaOptions = {}): {
  version: number;
  schemas: TableSchema[];
} {
  const controls: TableSchema = {
    modelName: "controls",
    fields: {
      id: { type: "string", required: true, unique: true },
      name: { type: "string", required: true },
      description: { type: "string", required: true },
      category: { type: "string", required: true },
      tags: { type: "json", required: false },
      createdAt: { type: "number", required: true },
      updatedAt: { type: "number", required: true },
    },
    indexes: [
      { name: ns(options, "controls_category_idx"), fields: ["category"] },
      { name: ns(options, "controls_updated_idx"), fields: ["updatedAt"] },
    ],
  };

  const frameworks: TableSchema = {
    modelName: "frameworks",
    fields: {
      id: { type: "string", required: true, unique: true },
      name: { type: "string", required: true },
      version: { type: "string", required: false },
      description: { type: "string", required: false },
      requirements: { type: "json", required: true },
      createdAt: { type: "number", required: true },
      updatedAt: { type: "number", required: true },
    },
    indexes: [
      { name: ns(options, "frameworks_updated_idx"), fields: ["updatedAt"] },
    ],
  };

  const evidence: TableSchema = {
    modelName: "evidence",
    fields: {
      id: { type: "string", required: true, unique: true },
      controlId: { type: "string", required: true },
      type: { type: "string", required: true },
      sourceId: { type: "string", required: false },
      frameworkRequirementId: { type: "string", required: false },
      timestamp: { type: "number", required: true },
      actorId: { type: "string", required: true },
      outcome: { type: "string", required: true },
      payload: { type: "json", required: false },
      artifactRef: { type: "string", required: false },
      createdAt: { type: "number", required: true },
    },
    indexes: [
      { name: ns(options, "evidence_control_idx"), fields: ["controlId"] },
      { name: ns(options, "evidence_timestamp_idx"), fields: ["timestamp"] },
      { name: ns(options, "evidence_type_idx"), fields: ["type"] },
      { name: ns(options, "evidence_created_idx"), fields: ["createdAt"] },
    ],
  };

  const checks: TableSchema = {
    modelName: "checks",
    fields: {
      id: { type: "string", required: true, unique: true },
      name: { type: "string", required: true },
      controlId: { type: "string", required: true },
      schedule: { type: "string", required: false },
      trigger: { type: "string", required: false },
      adapterName: { type: "string", required: false },
      adapterMethod: { type: "string", required: false },
      customConfig: { type: "json", required: false },
      createdAt: { type: "number", required: true },
      updatedAt: { type: "number", required: true },
    },
    indexes: [
      { name: ns(options, "checks_control_idx"), fields: ["controlId"] },
      { name: ns(options, "checks_updated_idx"), fields: ["updatedAt"] },
    ],
  };

  return {
    version: 1,
    schemas: [controls, frameworks, evidence, checks],
  };
}

export function getCompfnSchemaMap(options: CompfnSchemaOptions = {}): TableSchemaMap {
  const { schemas } = getCompfnSchema(options);
  return Object.fromEntries(schemas.map((s) => [s.modelName, s]));
}
import { describe, it, expect, beforeEach } from "vitest";
import { execSync } from "child_process";
import { writeFileSync, mkdirSync, rmSync, existsSync, readFileSync } from "fs";
import { resolve, join } from "path";

const CLI_PATH = resolve(__dirname, "../../cli/dist/index.js");
const TEST_DIR = resolve(__dirname, "../../.test-cli");
const CONFIG_PATH = join(TEST_DIR, "compfn.config.json");

function setupTestDir() {
  if (existsSync(TEST_DIR)) {
    rmSync(TEST_DIR, { recursive: true, force: true });
  }
  mkdirSync(TEST_DIR, { recursive: true });

  writeFileSync(
    CONFIG_PATH,
    JSON.stringify({
      database: { type: "memory" },
      namespace: "test",
    })
  );
}

function cleanupTestDir() {
  if (existsSync(TEST_DIR)) {
    rmSync(TEST_DIR, { recursive: true, force: true });
  }
}

describe("CLI Tests", () => {
  beforeEach(() => {
    setupTestDir();
  });

  describe("TV-CLI-001: init and run-checks", () => {
    it("init succeeds", () => {
      const output = execSync(`node ${CLI_PATH} init --config ${CONFIG_PATH}`, {
        encoding: "utf-8",
      });
      expect(output).toContain("CompFn initialized successfully");
    });

    it("run-checks runs (with no checks)", () => {
      execSync(`node ${CLI_PATH} init --config ${CONFIG_PATH}`, { encoding: "utf-8" });

      const output = execSync(`node ${CLI_PATH} run-checks --config ${CONFIG_PATH}`, {
        encoding: "utf-8",
      });
      expect(output).toContain("No checks to run");
    });
  });

  describe("TV-CLI-002: export and attest", () => {
    it("export writes file", () => {
      execSync(`node ${CLI_PATH} init --config ${CONFIG_PATH}`, { encoding: "utf-8" });

      const outputPath = join(TEST_DIR, "export.json");
      const output = execSync(
        `node ${CLI_PATH} export --output ${outputPath} --config ${CONFIG_PATH}`,
        { encoding: "utf-8" }
      );

      expect(output).toContain("Auditor pack exported");
      expect(existsSync(outputPath)).toBe(true);

      const content = readFileSync(outputPath, "utf-8");
      const parsed = JSON.parse(content);
      expect(parsed).toHaveProperty("exportedAt");
      expect(parsed).toHaveProperty("controls");
      expect(parsed).toHaveProperty("frameworks");
      expect(parsed).toHaveProperty("evidence");
      expect(parsed).toHaveProperty("mapping");
    });

    it("attest creates evidence", async () => {
      execSync(`node ${CLI_PATH} init --config ${CONFIG_PATH}`, { encoding: "utf-8" });

      const { compFn } = await import("compfn");
      const { memoryAdapter } = await import("@superfunctions/db/adapters");
      const { createSchemaIfSupported } = await import("compfn");

      const adapter = memoryAdapter({});
      await createSchemaIfSupported(adapter, { namespace: "test" });

      const api = compFn({
        database: adapter,
        namespace: "test",
      });

      const controlResult = await api.controls.create({
        name: "Test Control",
        description: "Test",
        category: "test",
      });

      expect(controlResult.ok).toBe(true);
      if (!controlResult.ok) throw new Error("Control creation failed");

      const controlId = controlResult.result.id;

      const attestResult = await api.evidence.create({
        controlId,
        type: "manual_attestation",
        actorId: "test-user",
        outcome: "pass",
      });

      expect(attestResult.ok).toBe(true);
      if (attestResult.ok) {
        expect(attestResult.result.type).toBe("manual_attestation");
        expect(attestResult.result.controlId).toBe(controlId);
      }
    });
  });
});

describe("CLI Tests (cleanup)", () => {
  it("cleanup test directory", () => {
    cleanupTestDir();
  });
});
import { writeFileSync } from "fs";
import { withConfig } from "../config.js";
import { compFn } from "compfn";

export async function exportCommand(options: {
  frameworkId?: string;
  output?: string;
  config?: string;
}): Promise<void> {
  return withConfig(options.config, async (config) => {
    const api = compFn(config);

    const exportResult = await api.export.auditorPack({
      frameworkId: options.frameworkId,
    });

    if (!exportResult.ok) {
      console.error(`Error exporting auditor pack: ${exportResult.error.message}`);
      process.exitCode = 1;
      return;
    }

    const json = JSON.stringify(exportResult.result, null, 2);

    if (options.output) {
      writeFileSync(options.output, json, "utf-8");
      console.log(`Auditor pack exported to ${options.output}`);
    } else {
      console.log(json);
    }

    return;
  });
}

