export type TestStatus = 'passed' | 'failed' | 'skipped' | 'timeout';
export type FrameworkType = 'vitest' | 'playwright' | 'jest' | 'puppeteer';
export type StorageType = 'indexeddb' | 'file' | 'db';
export type BrowserType = 'chromium' | 'firefox' | 'webkit';
export type ArtifactType = 'screenshot' | 'video' | 'trace' | 'log';

export interface TestFnConfig {
  framework: FrameworkType;
  testPattern?: string | string[];
  parallel?: number | 'auto';
  timeout?: number;
  retries?: number;
  env?: Record<string, string>;
  browsers?: BrowserType[] | BrowserConfig[];
  storage?: StorageConfig;
  visual?: VisualTestConfig;
  reporters?: Reporter[];
  onProgress?: (progress: TestProgress) => void;
  onComplete?: (results: TestResults) => void;
}

export interface StorageConfig {
  type: StorageType;
  dbName?: string;
  adapter?: unknown;
  retentionDays?: number;
}

export interface BrowserConfig {
  name: BrowserType;
  headless?: boolean;
  viewport?: { width: number; height: number };
  deviceScaleFactor?: number;
  userAgent?: string;
  locale?: string;
  timezone?: string;
  permissions?: string[];
  geolocation?: { latitude: number; longitude: number };
}

export interface VisualTestConfig {
  baselineDir: string;
  diffDir: string;
  threshold?: number;
  updateBaselines?: boolean;
  fullPage?: boolean;
}

export interface TestCase {
  id: string;
  file: string;
  name: string;
  suite?: string;
  tags?: string[];
}

export interface TestResult {
  id: string;
  status: TestStatus;
  duration: number;
  error?: TestError;
  artifacts?: Artifact[];
  metadata?: Record<string, unknown>;
}

export interface TestError {
  message: string;
  stack?: string;
  expected?: unknown;
  actual?: unknown;
  diff?: string;
}

export interface Artifact {
  type: ArtifactType;
  path: string;
  buffer?: Buffer;
  metadata?: Record<string, unknown>;
}

export interface TestProgress {
  completed: number;
  total: number;
  current?: TestCase;
}

export interface TestResults {
  id: string;
  timestamp: number;
  summary: TestRunSummary;
  results: TestResult[];
  artifacts?: ArtifactReference[];
}

export interface TestRunSummary {
  total: number;
  passed: number;
  failed: number;
  skipped: number;
  duration: number;
  coverage?: CoverageData;
}

export interface CoverageData {
  lines: number;
  statements: number;
  functions: number;
  branches: number;
}

export interface ArtifactReference {
  id: string;
  testId: string;
  type: ArtifactType;
  path: string;
