  runs: 'testfn_runs',
  results: 'testfn_results',
  artifacts: 'testfn_artifacts',
  metadata: 'testfn_metadata'
} as const;

type StoreName = typeof STORE_NAMES[keyof typeof STORE_NAMES];
type TransactionMode = 'readonly' | 'readwrite';

interface StorageInitOptions {
