/**
 * Drizzle adapter (SQLite) — Row-level namespace isolation integration test.
 *
 * Covers:
 *  - TST-001: Namespace isolation contract tests run against Drizzle adapter
 *  - RLN-011: Drizzle adapter compatibility with rowLevelNamespace
 *  - TV-DRZ-001: Full CRUD cycle with Drizzle adapter (SQLite) and namespace filtering
 *
 * Phase 5 deliverable:
 *  - Runs the reusable contract test suite (from Phase 1) with Drizzle + SQLite backend.
 *  - Verifies at SQL level that __ns values are physically stored.
 *  - Verifies that idx_task___ns is used by the SQLite query planner.
 */

import { describe, it, expect, beforeEach } from 'vitest';
import { drizzle } from 'drizzle-orm/better-sqlite3';
import { sqliteTable, text, index } from 'drizzle-orm/sqlite-core';
import Database from 'better-sqlite3';
import { drizzleAdapter } from '../index.js';
import { wrapWithRowLevelNamespace } from '../../../adapter/row-level-namespace.js';
import { runRowLevelNamespaceContractTests } from '../../../testing/namespace-contract-tests.js';
import type { Adapter } from '../../../adapter/types.js';

// ---------------------------------------------------------------------------
// Drizzle schemas:
//   taskStrict  — __ns NOT NULL  (used for SQL-level storage verification)
//   taskFlex    — __ns nullable   (used for contract tests, where disabled-mode
//                                  creates records without __ns)
// ---------------------------------------------------------------------------

const taskStrict = sqliteTable(
  'task',
  {
    id: text('id').primaryKey(),
    title: text('title'),
    status: text('status'),
    __ns: text('__ns').notNull(),
  },
  (table) => [index('idx_task___ns').on(table.__ns)],
);

const taskFlex = sqliteTable(
  'task',
  {
    id: text('id').primaryKey(),
    title: text('title'),
    status: text('status'),
    __ns: text('__ns'),  // nullable: contract tests test wrapper behaviour, not DB enforcement
  },
  (table) => [index('idx_task___ns').on(table.__ns)],
);

// ---------------------------------------------------------------------------
// Factories
// ---------------------------------------------------------------------------

/**
 * Factory for contract tests: uses nullable __ns so the disabled-mode test
 * (RLN-012) can insert records without __ns without hitting a NOT NULL error.
 * The application-level enforcement is verified by the wrapper, not the DB.
 */
function makeBaseAdapter(): { sqlite: Database.Database; adapter: Adapter } {
  const sqlite = new Database(':memory:');

  sqlite.exec(`
    CREATE TABLE task (
      id    TEXT PRIMARY KEY,
      title TEXT,
      status TEXT,
      __ns  TEXT
    );
    CREATE INDEX idx_task___ns ON task (__ns);
  `);

  const schema = { task: taskFlex };
  const db = drizzle(sqlite, { schema });

  const adapter = drizzleAdapter({
    db,
    dialect: 'sqlite',
    upsertKeys: { task: 'id' },
    debug: false,
  });

  return { sqlite, adapter };
}

/**
 * Factory for SQL-level verification: uses NOT NULL __ns column to prove that
 * the wrapper stamps every created row and the DB enforces the constraint.
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import {
  TestRunner,
  TestStorage,
  VisualTester,
  type TestCase,
  type TestFrameworkAdapter,
  type TestResult,
} from "@testfn/core";
import {
  MemoryAdminAuditSink,
  MemoryAdminIdempotencyStore,
  createAdminDispatcher,
  createAdminRegistry,
  type AdminOperationContext,
} from "@superfunctions/admin";
import {
  createTestFnDomainAdminAdapter,
  createTestFnAdminAdapter,
  createTestFnDomainAdminService,
  testFnAdminCapability,
  testFnAdminResources,
  type TestFnDomainAdminBinding,
} from "../index.js";

const temporaryDirectories: string[] = [];

function context(projectId: string, overrides: Partial<AdminOperationContext> = {}): AdminOperationContext {
  return {
    scope: {
      installationId: "installation_1",
      workspaceId: "workspace_1",
      projectId,
      environmentId: "environment_1",
      namespace: "tenant_1",
      region: "in-south",
    },
    actor: { id: "operator_1", type: "user", permissions: ["*"] },
    requestId: crypto.randomUUID(),
    correlationId: "correlation_1",
    source: "console",
    ...overrides,
  };
}

function testAdapter(projectId: string): TestFrameworkAdapter {
  return {
    name: `memory-${projectId}`,
    supports: () => true,
    async discover(): Promise<TestCase[]> {
      return [{ id: `test-${projectId}`, file: `${projectId}.test.ts`, name: "scope test" }];
    },
    async run(tests: TestCase[]): Promise<TestResult[]> {
      return tests.map((test) => ({
        id: test.id,
        status: "passed",
        duration: 12,
        artifacts: [{
          type: "log",
          path: `/private/${projectId}.log`,
          buffer: Buffer.from("operator secret"),
        }],
      }));
    },
  };
}

function domainBinding(projectId: string): TestFnDomainAdminBinding {
  const root = mkdtempSync(join(tmpdir(), `testfn-admin-${projectId}-`));
  temporaryDirectories.push(root);
  const runner = new TestRunner({ framework: "vitest", parallel: 1, reporters: [] });
  runner.setAdapter(testAdapter(projectId));
  return {
    runner,
    storage: new TestStorage({ type: "indexeddb", dbName: `testfn-admin-${projectId}-${crypto.randomUUID()}` }),
    visual: new VisualTester({ baselineDir: join(root, "baselines"), diffDir: join(root, "diffs") }),
    environment: { platform: "test", ci: true },
  };
}

function dispatcher(bindings: Map<string, TestFnDomainAdminBinding>) {
  const adapter = createTestFnDomainAdminAdapter({
    resolve: (adminContext) => {
      const binding = bindings.get(adminContext.scope.projectId ?? "");
      if (!binding) throw new Error("missing test binding");
      return binding;
    },
  });
  return createAdminDispatcher({
    registry: createAdminRegistry({ adapters: [adapter], enabledModules: ["testfn"] }),
    audit: new MemoryAdminAuditSink(),
    idempotency: new MemoryAdminIdempotencyStore(),
    confirmation: { verify: ({ token }) => token === "confirmed" },
  });
}

