 const shifted=testSignificance([1,1,1,1,1,1],[10,10,10,10,10,10]);expect(shifted.significant).toBe(true);expect(shifted).toEqual(testSignificance([1,1,1,1,1,1],[10,10,10,10,10,10]));expect(()=>testSignificance([NaN,1],[1,2])).toThrow();
});
