 const run:TestRun={id:'</script><script>globalThis.injected=true</script>',timestamp:Date.now(),environment:{platform:'test'},summary:{total:1,passed:1,failed:0,skipped:0,duration:4,coverage:{lines:90,functions:80,branches:70,statements:95}},results:[{id:'<b>case</b>',status:'passed',duration:4}]};await storage.saveRun(run);
 const analytics=new AnalyticsEngine(storage);analytics.registerMetric('double duration',value=>value.summary.duration*2);expect(await analytics.computeCustomMetrics(run.id)).toEqual({'double duration':8});expect((await analytics.getCoverageTrends())[0].coverage.lines).toBe(90);analytics.registerMetric('invalid',()=>NaN);await expect(analytics.computeCustomMetrics(run.id)).rejects.toThrow('finite');
 await generateDashboard(storage,dir);for(const file of ['index.html','test.html','visual.html','analytics.html']){const html=await readFile(join(dir,file),'utf8');expect(html).not.toContain('</script><script>globalThis.injected=true');expect(html).toContain('\\u003c/script>');expect(html).not.toContain('<script src=');}expect(JSON.parse(await readFile(join(dir,'data/runs.json'),'utf8'))).toHaveLength(1);
 }finally{await storage.close();await rm(dir,{recursive:true,force:true});}
});
