 await page.getByRole('link',{name:'Test details',exact:true}).click();check(await page.getByRole('combobox',{name:'Test'}).locator('option').count()===1000,'test identities');await page.getByRole('combobox',{name:'Test'}).selectOption('test-1');check(await page.locator('table tr').count()===101,'history table');await page.getByRole('link',{name:'Analytics',exact:true}).click();check(await page.getByRole('heading',{name:'Failure analysis',exact:true}).count()===1,'failure analysis');await page.getByRole('link',{name:'Visual diffs',exact:true}).click();check(await page.locator('iframe').count()===1,'embedded standalone visual viewer');
 await page.goto(`http://127.0.0.1:${server.address().port}`);const reset=await applyNetworkProfile(page,{name:'latency',downloadThroughput:10,uploadThroughput:10,latency:120});start=performance.now();await page.evaluate(()=>fetch('/data').then(r=>r.text()));metrics.networkLatencyMs=performance.now()-start;check(metrics.networkLatencyMs>=100,'actual CDP latency');await reset();const online=await applyNetworkProfile(page,networkProfiles.offline);check(await page.evaluate(()=>fetch('/data').then(()=>false,()=>true)),'offline blocks request');await online();check(await page.evaluate(()=>fetch('/data').then(r=>r.ok)),'cleanup restores network');
