 let large=false;const response=await eventStream(request(),{realtime,logger:createLogger(),query:async()=>({ok:true,result:large?result:{data:[],nextCursor:null}})});const reader=response.body!.getReader();let frames='';while(!frames.includes('query.snapshot'))frames+=new TextDecoder().decode((await reader.read()).value);large=true;realtime.broadcast(event);frames=new TextDecoder().decode((await reader.read()).value);expect(frames).toContain('PAYLOAD_TOO_LARGE');expect((await reader.read()).done).toBe(true);expect(realtime.getConnectionCount()).toBe(0);
});
